// Des: Unit tests for the aa-conf-main.json tunables
// Flo: apply JSON text > assert tune values, defaults on bad input
// I/O: JSON text > pass or fail
// ===================================================================
const std = @import("std"); const stor = @import("st-conf-stor.zig"); const tszz = std.testing;
test "empty object keeps every default, no warning" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); try tszz.expect(stor.confApply(aren.allocator(), "{}") == null); try tszz.expectEqual(@as(u16, 4000), stor.tune.port); try tszz.expectEqual(@as(u32, 4), stor.tune.workers); try tszz.expectEqual(@as(u32, 64), stor.tune.hist_maxz); try tszz.expectEqual(@as(u32, 86400), stor.tune.tmoz_seco); try tszz.expectEqualStrings(".ac-auto-task", stor.tune.data); }
test "valid keys override, unknown keys are ignored" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); try tszz.expect(stor.confApply(aren.allocator(), "{\"port\":4040,\"jobs_same_time\":2,\"cmds_hist_maxz\":50,\"time_limi_seco\":120,\"apps_data_loca\":\".my-state\",\"zzz\":1}") == null); try tszz.expectEqual(@as(u16, 4040), stor.tune.port); try tszz.expectEqual(@as(u32, 2), stor.tune.workers); try tszz.expectEqual(@as(u32, 50), stor.tune.hist_maxz); try tszz.expectEqual(@as(u32, 120), stor.tune.tmoz_seco); try tszz.expectEqualStrings(".my-state", stor.tune.data); }
test "out-of-range and wrong-type values fall back to defaults and warn" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); try tszz.expect(stor.confApply(aren.allocator(), "{\"port\":0,\"jobs_same_time\":9,\"cmds_hist_maxz\":\"x\",\"time_limi_seco\":99999999,\"apps_data_loca\":\"../up\"}") != null); try tszz.expectEqual(@as(u16, 4000), stor.tune.port); try tszz.expectEqual(@as(u32, 4), stor.tune.workers); try tszz.expectEqual(@as(u32, 64), stor.tune.hist_maxz); try tszz.expectEqual(@as(u32, 86400), stor.tune.tmoz_seco); try tszz.expectEqualStrings(".ac-auto-task", stor.tune.data); }
test "one bad key does not drop the good ones" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); try tszz.expect(stor.confApply(aren.allocator(), "{\"port\":4041,\"jobs_same_time\":0}") != null); try tszz.expectEqual(@as(u16, 4041), stor.tune.port); try tszz.expectEqual(@as(u32, 4), stor.tune.workers); }
test "broken JSON and non-object roots use defaults and warn" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); try tszz.expect(stor.confApply(aren.allocator(), "{oops") != null); try tszz.expectEqual(@as(u16, 4000), stor.tune.port); try tszz.expect(stor.confApply(aren.allocator(), "[1]") != null); try tszz.expectEqual(@as(u16, 4000), stor.tune.port); }
